shaderSource:
uniform float2 resolution;
uniform float time;

float hash(float2 p) {
  return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}

float valueNoise(float2 p) {
  float2 i = floor(p);
  float2 f = fract(p);
  float2 u = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + float2(1.0, 0.0));
  float c = hash(i + float2(0.0, 1.0));
  float d = hash(i + float2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float turbulence(float2 p) {
  float v = valueNoise(p) * 0.56;
  v += valueNoise(p * 2.07 + 13.4) * 0.27;
  v += valueNoise(p * 4.13 + 7.1) * 0.12;
  v += valueNoise(p * 8.21 + 3.8) * 0.05;
  return v;
}

half4 main(float2 xy) {
  float2 safeResolution = max(resolution, float2(1.0));
  float2 uv = xy / safeResolution;
  float aspect = safeResolution.x / safeResolution.y;

  float leftEdge = uv.x * aspect;
  float rightEdge = (1.0 - uv.x) * aspect;
  float topEdge = uv.y;
  float bottomEdge = 1.0 - uv.y;
  float edgeDistance = min(min(leftEdge, rightEdge), min(topEdge, bottomEdge));

  float2 flowA = float2(uv.x * aspect * 7.5 + uv.y * 2.8, uv.y * 9.0 - time * 2.7);
  float2 flowB = float2(uv.y * 11.0 - time * 1.8, uv.x * aspect * 6.2 + time * 2.2);
  float noiseA = turbulence(flowA);
  float noiseB = turbulence(flowB);
  float flameNoise = clamp(noiseA * 0.68 + noiseB * 0.42, 0.0, 1.0);

  float pulse = 0.86 + 0.14 * sin(time * 3.1 + uv.x * 9.0 - uv.y * 7.0);
  float flameDepth = (0.045 + flameNoise * 0.115) * pulse;
  float flame = 1.0 - smoothstep(flameDepth * 0.34, flameDepth, edgeDistance);
  float core = 1.0 - smoothstep(0.0, 0.032, edgeDistance);
  float tendrils = smoothstep(0.52, 0.94, flameNoise) *
    (1.0 - smoothstep(flameDepth * 0.45, flameDepth * 1.35, edgeDistance));
  float innerHeat = exp(-edgeDistance * 20.0) * (0.66 + flameNoise * 0.34);

  float2 centered = (uv - float2(0.5)) * float2(aspect, 1.0);
  float vignette = smoothstep(0.12, 0.78, length(centered));
  half3 blackBody = mix(half3(0.003, 0.008, 0.004), half3(0.008, 0.018, 0.010), vignette);

  half3 emberGreen = half3(0.005, 0.24, 0.035);
  half3 neonGreen = half3(0.02, 0.96, 0.16);
  half3 hotGreen = half3(0.48, 1.0, 0.58);
  half3 whiteCore = half3(0.86, 1.0, 0.89);

  half3 fire = mix(emberGreen, neonGreen, smoothstep(0.08, 0.56, flame));
  fire = mix(fire, hotGreen, smoothstep(0.50, 0.90, flame * flameNoise + core * 0.45));
  fire = mix(fire, whiteCore, smoothstep(0.78, 1.18, core + tendrils * 0.52));

  half3 color = blackBody;
  color += fire * flame * (0.48 + flameNoise * 0.72);
  color += neonGreen * tendrils * 0.88;
  color += hotGreen * innerHeat * 0.10;
  color += whiteCore * core * (0.32 + 0.18 * sin(time * 4.4 + uv.x * 15.0));

  float centerGuard = smoothstep(0.04, 0.18, edgeDistance);
  color = mix(color, blackBody, centerGuard * 0.92);
  color += neonGreen * (1.0 - centerGuard) * 0.035;

  return half4(clamp(color, half3(0.0), half3(1.0)), 1.0);
}
